BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT105-S4-Q20$batch05$ AND q.stimulus=$batch05$James: Chemists have recently invented a new technique for extracting rhodium, an element necessary for manufacturing catalytic converters for automobiles, from nuclear waste. Catalytic converters function to remove noxious gases from automobile exhaust. The use of nuclear power is therefore contributing in at least one way to creating a cleaner environment.

Marta: The technique you mention, though effective, is still at an experimental stage, so there has been no shift in the sources of the rhodium currently used in manufacturing catalytic converters.$batch05$ AND q.prompt=$batch05$Marta responds to James's argument by$batch05$ AND q.correct_choice=$batch05$D$batch05$) THEN RAISE EXCEPTION 'Question changed: PT105-S4-Q20'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch05$PT105-S4-Q20$batch05$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT105-S4-Q20'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT105-S4-Q20$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$(Marta, implied) Nuclear power is not yet making the environment cleaner in this way.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$The extraction technique is still experimental, so the rhodium in catalytic converters still comes from the same sources as before.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$Marta grants the technique works ("though effective"). What James overlooked is the gap between "can be done" and "is being done." His conclusion says nuclear power *is contributing*. Marta points out it is not contributing yet.$batch05$), (3, $batch05$Goal$batch05$, $batch05$Pointing out a fact James did not take into account.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT105-S4-Q20$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$Marta accepts James's claims, even calling the technique effective. That is the second-speaker rule at work. She attacks the step to his conclusion, not his facts.$batch05$), ($batch05$B$batch05$, $batch05$No one's credibility comes up.$batch05$), ($batch05$C$batch05$, $batch05$This is the most popular wrong answer. But James's argument is not circular. His premises (rhodium can come from nuclear waste and is used in converters) are different from his conclusion (nuclear power is helping now).$batch05$), ($batch05$D$batch05$, $batch05$The fact is that the technique is still experimental and has not changed where rhodium comes from. James did not account for it, and it breaks his "is contributing."$batch05$), ($batch05$E$batch05$, $batch05$Marta does not compare how plausible James's premises are with his conclusion.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT105-S4-Q20$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
